static int alloc_node(Filter* f, FilterNodeType type) {
    if (f->node_count >= 64) return -1;
    int idx = f->node_count++;
    f->nodes[idx].type = type;
    f->nodes[idx].left_child = -1;
    f->nodes[idx].right_child = -1;
    return idx;
}

