    for (int i = 1; i < scope.count; i++) {
        if (use_hash[i]) join_index_destroy(&join_indexes[i]);
    }
    if (right_matched) free(right_matched);
    if (results) free(results);
    if (rows) free(rows);
    if (groups) free(groups);
    free(joins);
    free(filter);
