static bool valid_thumbprint(const char* value) {
    if (strlen(value) != 40) return false;
    for (size_t i = 0; i < 40; i++)
        if (!is_ascii_digit(value[i]) &&
            (uppercase_ascii(value[i]) < 'A' || uppercase_ascii(value[i]) > 'F'))
            return false;
    return true;
}

